const raw = $input.first().json.output;

try {
  let cleaned = String(raw)
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  const start = cleaned.indexOf("{");
  const end = cleaned.lastIndexOf("}");

  if (start === -1 || end === -1) {
    throw new Error("No JSON object found");
  }

  cleaned = cleaned.substring(start, end + 1);

  const report = JSON.parse(cleaned);

  return [
    {
      json: {
        report_type:
          report.report_type ||
          "AI Web Form Lead Routing Report",

        lead:
          report.lead || {},

        lead_analysis:
          report.lead_analysis || {},

        lead_scoring:
          report.lead_scoring || {},

        routing:
          report.routing || {},

        follow_up:
          report.follow_up || {},

        evidence:
          report.evidence || [],

        final_assessment:
          report.final_assessment || "Unknown",

        parse_status: "success"
      }
    }
  ];

} catch (error) {

  return [
    {
      json: {
        report_type:
          "AI Web Form Lead Routing Report",

        parse_status: "failed",

        parse_error: error.message,

        raw_output: raw
      }
    }
  ];
}
